#include "workload.hpp"
#include "engine.hpp"
#include <algorithm>
#include <chrono>
#include <random>
#include <sstream>
std::string runWorkload(Engine& engine,int operations,int readRatio,int deleteRatio,int keySpace,int payloadSize){operations=std::clamp(operations,0,100000);readRatio=std::clamp(readRatio,0,100);deleteRatio=std::clamp(deleteRatio,0,100-readRatio);keySpace=std::max(1,keySpace);payloadSize=std::clamp(payloadSize,1,1048576);std::mt19937 rng(42);std::uniform_int_distribution<int> key(0,keySpace-1),coin(0,99);int reads=0,writes=0,deletes=0;auto start=std::chrono::steady_clock::now();for(int i=0;i<operations;++i){std::string k="sim-"+std::to_string(key(rng));int c=coin(rng);if(c<readRatio){std::string value;engine.get(k,value);++reads;}else if(c<readRatio+deleteRatio){engine.del(k);++deletes;}else{engine.put(k,std::string(payloadSize,'x'));++writes;}}double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::ostringstream out;out<<"{\"operations\":"<<operations<<",\"reads\":"<<reads<<",\"writes\":"<<writes<<",\"deletes\":"<<deletes<<",\"throughput\":"<<(operations/std::max(seconds,0.000001))<<"}";return out.str();}
std::string runBenchmark(Engine& engine,int operations,int readRatio,int keySpace,int payloadSize,int crashAt){operations=std::clamp(operations,0,100000);crashAt=std::clamp(crashAt,0,operations);std::mt19937 rng(42);std::uniform_int_distribution<int> key(0,std::max(1,keySpace)-1),coin(0,99);int reads=0,writes=0;for(int i=0;i<operations;++i){std::string k="bench-"+std::to_string(key(rng));if(coin(rng)<readRatio){std::string value;engine.get(k,value);++reads;}else{engine.put(k,std::string(std::max(1,payloadSize),'x'));++writes;}if(crashAt>0&&i+1==crashAt)engine.crashRecover();}std::ostringstream out;out<<"{\"operations\":"<<operations<<",\"reads\":"<<reads<<",\"writes\":"<<writes<<",\"crashRecovered\":"<<(crashAt>0?"true":"false")<<"}";return out.str();}
